   marker=page.locator('.company-city-reference');marker.focus();marker.press('Space');expect(page.locator('.leaflet-popup-content')).to_contain_text('not a facility');page.locator('.leaflet-popup-content [data-record-id="'+fid+'"]').press('Enter');expect(page.locator('#profileTitle')).to_have_text('Floating Rock Studio');expect(page.locator('#detailContent')).to_contain_text('Separate approximate company reference');expect(page.locator('#detailContent')).to_contain_text('not locate its entrance');expect(page.locator('#detailContent')).to_contain_text('Class C');page.locator('#close').click()
   passed('real Floating Rock Animation/country/Class C/company filters reach a distinct city-reference marker and existing keyboard profile without changing coordinates')
