   passed('CSV preserves null original coordinates and separate licensed reference metadata; reference layer can be hidden without losing the company')
   page.locator('#resetFilters').click();page.locator('#advancedFilters').evaluate('(d)=>d.open=true');page.locator('#search').fill('Frame Machine');page.locator('#category').select_option('Animation');page.locator('#country').select_option('United States');page.locator('#evidenceClass').select_option('C');page.locator('#recordKind').select_option('source_location');expect(page.locator('#count')).to_have_text('1 record');page.locator('#fitResults').click();assert page.evaluate('(id)=>layer.getLayers().some(m=>m.motionxLocations.includes(id))',frame);page.locator('#list a[data-id="'+frame+'"]').click();expect(page.locator('#profileTitle')).to_have_text('Frame Machine');expect(page.locator('#detailContent')).to_contain_text('not independently verified');page.locator('#close').click();page.locator('#confirmedOnly').check();expect(page.locator('#count')).to_have_text('0 records');page.locator('#confirmedOnly').uncheck();page.locator('#recordKind').select_option('company_reference');expect(page.locator('#count')).to_have_text('0 records');expect(page.locator('.empty-state')).to_contain_text('source-location observations')
   passed('real Frame Machine retains its original source point/Class C; company-only and verified-capability filters explain exclusions instead of inventing a facility')
   page.locator('#resetFilters').click();page.evaluate('map.setView([-41.28664,174.77557],16,{animate:false})');expect(page.locator('.company-city-reference')).to_have_count(1);page.locator('.company-city-reference').click();expect(page.locator('.leaflet-popup-content [data-record-id="'+fid+'"]').first).to_be_visible();expect(page.locator('.leaflet-popup-content [data-record-id="weta-fx-wellington"]').first).to_be_visible()
   passed('identical-coordinate selector includes company reference and retained Wellington location with explicit display-type distinction and no coordinate offset')
